-- Background jobs do their actions once (BACKEND_SPEC §10): marks of what a job did per subject and occurrence, the cleanup of test SMS codes and old marks, the job catalog of services/jobs.ts.
-- Generated by scripts/gen-schema.mjs from packages/domain/src/store/sql/migrationsJobs.ts. Do not edit by hand:
-- change the TypeScript source and run `node scripts/gen-schema.mjs`.

-- What a job already did: one row per (job, subject, occurrence) — a reminder of one SLA breach, the renewal deal of
-- one policy, the request about one child's age limit. The insert commits with the action (one transaction of the
-- worker): a run that fails leaves no mark, a second run finds the mark and does nothing.
create table app.job_marks (
  job text not null check (length(job) between 1 and 64),
  subject text not null check (length(subject) between 1 and 200),
  occurrence text not null check (length(occurrence) between 1 and 200),
  "at" timestamptz not null default now(),
  primary key (job, subject, occurrence)
);
create index job_marks_at_idx on app.job_marks ("at");
comment on table app.job_marks is 'Actions of background jobs done once per subject and occurrence (repo jobMarks). System only: the worker.';
alter table app.job_marks enable row level security;
revoke all on app.job_marks from public, anon, authenticated;
grant select, insert, delete on app.job_marks to service_role;

-- Expired sessions, challenges, attempt counters and tokens (epoch columns are milliseconds).
create or replace function app.job_cleanup_expired() returns jsonb
  language plpgsql volatile security definer set search_path = ''
as $$
declare
  v_now bigint := (extract(epoch from now()) * 1000)::bigint;
  v_day bigint := 24 * 3600 * 1000;
  v jsonb := '{}'::jsonb;
  n bigint;
begin
  delete from public.sessions where last_activity < v_now - 12 * 3600 * 1000; get diagnostics n = row_count; v := v || jsonb_build_object('sessions', n);
  delete from public.challenges where expires_at < v_now; get diagnostics n = row_count; v := v || jsonb_build_object('challenges', n);
  delete from public.grants where expires_at < v_now; get diagnostics n = row_count; v := v || jsonb_build_object('grants', n);
  delete from public.lockouts where until < v_now; get diagnostics n = row_count; v := v || jsonb_build_object('lockouts', n);
  delete from public.login_failures where "at" < v_now - v_day; get diagnostics n = row_count; v := v || jsonb_build_object('login_failures', n);
  delete from public.check_attempts where "at" < v_now - v_day; get diagnostics n = row_count; v := v || jsonb_build_object('check_attempts', n);
  delete from public.check_locks where until < v_now; get diagnostics n = row_count; v := v || jsonb_build_object('check_locks', n);
  delete from public.card_tokens where expires_at < v_now; get diagnostics n = row_count; v := v || jsonb_build_object('card_tokens', n);
  delete from public.access_tokens where expires_at < v_now; get diagnostics n = row_count; v := v || jsonb_build_object('access_tokens', n);
  delete from public.idempotency where "at" < v_now - v_day; get diagnostics n = row_count; v := v || jsonb_build_object('idempotency', n);
  delete from public.api_calls where "at" < v_now - 3600 * 1000; get diagnostics n = row_count; v := v || jsonb_build_object('api_calls', n);
  delete from public.sessions s using public.app_sessions a where a.session_id = s.id and a.last_activity < now() - interval '31 minutes'; get diagnostics n = row_count; v := v || jsonb_build_object('app_sessions', n);
  delete from public.app_auth_challenges where expires_at < now(); get diagnostics n = row_count; v := v || jsonb_build_object('app_auth_challenges', n);
  delete from app.job_queue where done_at < now() - interval '7 days'; get diagnostics n = row_count; v := v || jsonb_build_object('job_queue', n);
  delete from app.test_phone_codes where "at" < now() - interval '5 minutes'; get diagnostics n = row_count; v := v || jsonb_build_object('test_phone_codes', n);
  delete from app.job_marks where "at" < now() - interval '400 days'; get diagnostics n = row_count; v := v || jsonb_build_object('job_marks', n);
  return v;
end $$;

revoke execute on function app.job_cleanup_expired() from public, authenticated;

-- Audit entries of the job's lifecycle transitions (and of the same transitions on read).
alter table public.audit_log drop constraint audit_log_action_check;
alter table public.audit_log add constraint audit_log_action_check check (action in ('login', 'logout', 'login_failed', 'reveal_pii', 'open_medical', 'limit_change_request', 'limit_change_approve', 'limit_change_reject', 'claim_transition', 'export', 'role_change', 'user_deactivate', 'hr_add_employee', 'hr_exclude_employee', 'hr_import', 'kp_created', 'kp_sent', 'kp_revoked', 'kp_downloaded', 'clinic_check_patient', 'clinic_check_failed', 'guarantee_requested', 'guarantee_decided', 'registry_submitted', 'registry_line_decided', 'registry_paid', 'integration_key_created', 'integration_key_revoked', 'webhook_created', 'policy_issued', 'policy_change_requested', 'policy_change_decided', 'assistance_assigned', 'case_created', 'guarantee_escalated', 'clinic_payment_recorded', 'rebill_submitted', 'rebill_line_decided', 'rebill_paid', 'qa_reviewed', 'complaint_resolved', 'dms_param_proposed', 'dms_param_changed', 'dms_param_rejected', 'authority_proposed', 'authority_changed', 'authority_rejected', 'lead_created', 'deal_stage_changed', 'deal_lost', 'census_uploaded', 'quote_saved', 'quote_submitted', 'quote_approved', 'quote_rejected', 'kp_accepted', 'kp_declined', 'contract_created', 'contract_updated', 'contract_legal_submitted', 'contract_legal_approved', 'contract_legal_returned', 'contract_finance_approved', 'contract_sent', 'contract_signed', 'contract_scan_uploaded', 'contract_scan_verified', 'contract_original', 'contract_activated', 'contract_terminated', 'contract_expired', 'policy_expired', 'payment_recorded', 'payments_imported', 'payment_allocated', 'change_request_created', 'endorsement_created', 'endorsement_signed', 'claim_opinion_requested', 'claim_opinion_given', 'claim_decided', 'claim_decision_escalated', 'claim_decision_rejected', 'claim_reserve_changed', 'claim_created', 'claim_flag_dismissed', 'claim_appealed', 'claim_appeal_resolved', 'ai_settings_proposed', 'ai_settings_changed', 'ai_settings_rejected', 'ai_kill_switch', 'ai_feedback', 'migration_validated', 'migration_submitted', 'migration_applied', 'migration_rejected', 'migration_rolled_back', 'migration_scan_attached', 'family_consent_granted', 'family_consent_revoked', 'family_request_created', 'family_request_decided', 'payout_card_changed', 'task_created', 'task_done', 'task_taken', 'task_rejected', 'task_reminded'));

-- The catalog follows services/jobs.ts (the schedules are unchanged).
update app.job_catalog set command = 'reminders.slaReminders', description = 'SLA of claims, guarantee letters, appointments awaiting the clinic and assistance cases: the responsible people are notified once per breach.' where name = 'sla-reminders';
update app.job_catalog set command = 'reminders.salesReminders (leadIdleDays, kpNoAnswerDays)', description = 'Leads without activity and commercial offers without an answer: the deal manager is notified once per state (06:07 Tashkent).' where name = 'sales-reminders';
update app.job_catalog set command = 'deals.openRenewalDeals (renewalLeadDays)', description = 'The renewal deal N days before the policy ends, once per policy (06:13 Tashkent).' where name = 'renewal-deals';
update app.job_catalog set command = 'lifecycle.contractLifecycle', description = 'Contracts entering into force, contracts and policies expiring after the end date; audited (00:05 Tashkent).' where name = 'contract-lifecycle';
update app.job_catalog set command = 'reminders.ageLimitTasks', description = 'Children reaching the age limit (maxChildAge / studentMaxAge): a request to the underwriter once per child and limit (06:21 Tashkent).' where name = 'child-age-limit';
update app.job_catalog set command = 'select app.job_cleanup_expired()', description = 'Expired sessions, login challenges, attempt counters, lockouts, card tokens, partner tokens, idempotency keys, test SMS codes and old job marks.' where name = 'cleanup-expired';
